// Non-secret settings only. The client SECRET lives in the n8n credential on the "Get Token" node (encrypted by n8n),
// never in this JSON. clientId is not secret: it is sent as the API-key header and must equal the token's azp claim.
// `sources` is generated from integration/extract_load.py SOURCES, so n8n and the Python loader share one definition.
return [{ json: {
  baseUrl: 'https://REPLACE-WITH-PUBLIC-MOCK-API-URL',
  tokenUrl: 'https://dev-z1apvxcaj6hhb84a.us.auth0.com/oauth/token',
  audience: 'https://myob-mock.dagostino-demo',
  clientId: 'REPLACE-WITH-AUTH0-M2M-CLIENT-ID',
  sources: [{"resource": "GeneralLedger/Account", "table": "myob_accounts", "path": "/accountright/{cf}/GeneralLedger/Account", "items": "Items", "next": "NextPageLink", "count": "Count", "id_key": "UID", "updated": "LastModified", "since_param": "$filter", "page_params": {"$top": 400}, "key_header": "x-myobapi-key", "myob": true}, {"resource": "Contact/Customer", "table": "myob_customers", "path": "/accountright/{cf}/Contact/Customer", "items": "Items", "next": "NextPageLink", "count": "Count", "id_key": "UID", "updated": "LastModified", "since_param": "$filter", "page_params": {"$top": 400}, "key_header": "x-myobapi-key", "myob": true}, {"resource": "Sale/Invoice/Service", "table": "myob_invoices", "path": "/accountright/{cf}/Sale/Invoice/Service", "items": "Items", "next": "NextPageLink", "count": "Count", "id_key": "UID", "updated": "LastModified", "since_param": "$filter", "page_params": {"$top": 400}, "key_header": "x-myobapi-key", "myob": true}, {"resource": "Sale/CustomerPayment", "table": "myob_customer_payments", "path": "/accountright/{cf}/Sale/CustomerPayment", "items": "Items", "next": "NextPageLink", "count": "Count", "id_key": "UID", "updated": "LastModified", "since_param": "$filter", "page_params": {"$top": 400}, "key_header": "x-myobapi-key", "myob": true}, {"resource": "leap:matters", "table": "leap_matters", "path": "/leap/v1/matters", "items": "data", "next": "paging.nextPage", "count": "paging.totalRecords", "id_key": "matterId", "updated": "lastModified", "since_param": "updatedSince", "page_params": {"pageSize": 200}, "key_header": null, "myob": false}, {"resource": "leap:invoices", "table": "leap_invoices", "path": "/leap/v1/invoices", "items": "data", "next": "paging.nextPage", "count": "paging.totalRecords", "id_key": "invoiceId", "updated": "lastModified", "since_param": "updatedSince", "page_params": {"pageSize": 200}, "key_header": null, "myob": false}, {"resource": "leap:trust/balances", "table": "leap_trust_balances", "path": "/leap/v1/trust/balances", "items": "data", "next": "paging.nextPage", "count": "paging.totalRecords", "id_key": "ledgerId", "updated": "lastModified", "since_param": "updatedSince", "page_params": {"pageSize": 200}, "key_header": null, "myob": false}, {"resource": "triconvey:matters", "table": "triconvey_matters", "path": "/smokeball/matters", "items": "value", "next": "next.href", "count": "size", "id_key": "id", "updated": "lastUpdated", "since_param": "LastUpdated", "page_params": {"Limit": 200}, "key_header": "x-api-key", "myob": false}, {"resource": "triconvey:trust/balances", "table": "triconvey_trust_balances", "path": "/smokeball/trust/balances", "items": "value", "next": "next.href", "count": "size", "id_key": "id", "updated": "lastUpdated", "since_param": "LastUpdated", "page_params": {"Limit": 200}, "key_header": "x-api-key", "myob": false}, {"resource": "infotrack:orders", "table": "infotrack_orders", "path": "/infotrack/v1/orders", "items": "orders", "next": "nextPageUrl", "count": "totalCount", "id_key": "orderId", "updated": "lastModified", "since_param": "modifiedSince", "page_params": {"pageSize": 1000}, "key_header": null, "myob": false}, {"resource": "pexa:workspaces", "table": "pexa_workspaces", "path": "/pexa/v1/workspaces", "items": "workspaces", "next": "links.next", "count": "totalCount", "id_key": "workspaceId", "updated": "lastUpdated", "since_param": "updatedSince", "page_params": {"limit": 100}, "key_header": null, "myob": false}],
}}];

// Pull every source (MYOB, LEAP, triConvey, InfoTrack, PEXA) with its own paging style + incremental watermark.
const cfg = $('Config').first().json;
const wmRows = $('Get Watermarks').all().map(i => i.json).filter(r => r.RESOURCE);
const watermarks = Object.fromEntries(wmRows.map(r => [r.RESOURCE, r.WATERMARK]));
const asJson = r => (typeof r === 'string' ? JSON.parse(r) : r);
const dig = (o, path) => path.split('.').reduce((v, k) => (v == null ? v : v[k]), o);
const tok = $('Get Token').first().json;                // one OAuth token per run (Auth0 free plan meters M2M tokens)
const headersFor = src => {
  const h = { Authorization: `Bearer ${tok.access_token}`, Accept: 'application/json' };
  if (src.myob) { h['x-myobapi-key'] = cfg.clientId; h['x-myobapi-version'] = 'v2'; }
  else if (src.key_header) { h[src.key_header] = cfg.clientId; }
  return h;
};
const myobHeaders = headersFor({ myob: true });
const cf = asJson(await this.helpers.httpRequest({ method: 'GET', url: `${cfg.baseUrl}/accountright/`, headers: myobHeaders }))[0];

const batchId = $execution.id + '-' + Date.now();
const loadedAt = new Date().toISOString().slice(0, 19);
const rows = [], audits = [];

for (const src of cfg.sources) {
  const since = watermarks[src.resource] || null;
  const qs = new URLSearchParams(src.page_params);
  if (since) qs.set(src.since_param, src.myob ? `LastModified gt datetime'${since}'` : since);
  let url = `${cfg.baseUrl}${src.path.replace('{cf}', cf.Id)}?${qs.toString()}`;
  let items = [], apiCount = null, status = 'OK';
  try {
    while (url) {
      const body = asJson(await this.helpers.httpRequest({ method: 'GET', url, headers: headersFor(src) }));
      items = items.concat(body[src.items]);
      apiCount = dig(body, src.count) ?? apiCount;
      url = dig(body, src.next);
    }
    if (apiCount !== items.length) status = 'COUNT_MISMATCH';
  } catch (e) {
    status = ('ERROR: ' + e.message).slice(0, 200); apiCount = -1; items = [];
  }
  for (const it of items) {
    rows.push({ TARGET_TABLE: src.table, RECORD_UID: String(it[src.id_key]), PAYLOAD_TEXT: JSON.stringify(it),
                LAST_MODIFIED: it[src.updated], BATCH_ID: batchId, LOADED_AT: loadedAt });
  }
  const newWm = items.reduce((m, it) => (it[src.updated] && it[src.updated] > (m || '') ? it[src.updated] : m), since);
  audits.push({ BATCH_ID: batchId, RESOURCE: src.resource, API_COUNT: apiCount,
                LOADED_COUNT: items.length, WATERMARK: newWm, STATUS: status, LOADED_AT: loadedAt });
}
const company = { COMPANY_FILE_UID: cf.Id, NAME: cf.Name, LAST_SYNC_DATE: cf.LastSyncDate, BATCH_ID: batchId, LOADED_AT: loadedAt };
return [{ json: { batchId, rows, audits, company } }];

const bad = $('Extract from Sources').first().json.audits.filter(a => a.STATUS !== 'OK');
if (bad.length) {
  throw new Error('Load problems: ' + bad.map(b => `${b.RESOURCE}=${b.STATUS}`).join('; '));
}
return [{ json: { ok: true, loaded: $('Extract from Sources').first().json.rows.length } }];
